def compute(vars):
    net_income_after_taxes = vars["Net Income After Taxes (NIAT)"]
    revenue = vars["Revenue"]
    multiplier = vars["100"]

    try:
        net_profit_margin = (net_income_after_taxes / revenue) * multiplier
    except ZeroDivisionError:
        return None

    return {
        "value": net_profit_margin,
        "trace": {
            "Net Income After Taxes (NIAT)": net_income_after_taxes,
            "Revenue": revenue,
            "100": multiplier,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
